INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'EN_ATENCION','Atención demo iniciada.',TIMESTAMPTZ '2026-10-01 10:10:00+00',u."Id",'40000000-0000-4000-8000-000000000001',NULL,NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000002' AND u."Username"='tecnico1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'SEGUIMIENTO','Demo: cableado revisado.',TIMESTAMPTZ '2026-10-01 10:30:00+00',u."Id",'40000000-0000-4000-8000-000000000002',NULL,(SELECT MIN(e."Id") FROM public."Evidences" e WHERE e."TicketId"=t."Id" AND e."Description"='Demo: cableado revisado.') FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000002' AND u."Username"='tecnico1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
